import { test, expect } from '@playwright/test';

test.describe('Browser Push Notification for Urgent Alerts', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should display push notification for urgent alerts', async ({ page }) => {
    // Set up push notification API
    await page.route('**/api/notifications/push', async (route) => {
      await route.continue();
    });

    // Mock urgent alert notification
    await page.route('**/api/notifications/push', async (route) => {
      await route.abort();
    }, { method: 'POST', body: JSON.stringify({
      type: 'urgent',
      title: 'System Failure',
      body: 'Critical system error detected. Immediate action required.',
      icon: 'alert',
      badge: '1'
    }) });

    // Verify notification is visible
    const notification = page.getByRole('alert');
    await expect(notification).toBeVisible();

    // Verify notification title and body
    await expect(notification).toContainText('System Failure');
    await expect(notification).toContainText('Critical system error detected. Immediate action required.');

    // Verify notification icon
    const icon = page.getByTestId('notification-icon');
    await expect(icon).toBeVisible();
    await expect(icon).toHaveAttribute('aria-label', 'Alert');

    // Verify notification badge
    const badge = page.getByTestId('notification-badge');
    await expect(badge).toBeVisible();
    await expect(badge).toHaveAttribute('data-badge', '1');

    // Verify notification dismiss button
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();

    // Verify notification is removed from the list
    const notificationList = page.getByTestId('notification-list');
    await expect(notificationList).toContainText('System Failure');

    // Verify notification count is updated
    const notificationCount = page.getByTestId('notification-count');
    await expect(notificationCount).toContainText('1');

    // Verify notification is removed from the list
    await expect(notificationList).not.toContainText('System Failure');
  });

  test('should not display push notification for non-urgent alerts', async ({ page }) => {
    // Mock non-urgent notification
    await page.route('**/api/notifications/push', async (route) => {
      await route.continue();
    }, { method: 'POST', body: JSON.stringify({
      type: 'info',
      title: 'New Feature Available',
      body: 'Explore our new feature in the app.',
      icon: 'info',
      badge: '0'
    }) });

    // Verify notification is not displayed
    const notification = page.getByRole('alert');
    await expect(notification).not.toBeVisible();

    // Verify notification list is empty
    const notificationList = page.getByTestId('notification-list');
    await expect(notificationList).toBeEmpty();

    // Verify notification count is zero
    const notificationCount = page.getByTestId('notification-count');
    await expect(notificationCount).toContainText('0');
  });
});
